// @vitest-environment node
/**
 * The placeholder schedule fixture (`fixtures/schedule-2026/`, generated by
 * `scripts/build-schedule-fixture.mjs`; plan `docs/changes/2026-11-03-schedule-expansion.md`
 * section 4.9, PR 4 task D1).
 *
 * What this holds, and what it does NOT take from anywhere:
 *
 *   - **The files are the generator's output.** A checked-in file that differs from a fresh build
 *     fails, and the script's own `--check` is run for real, on the real directory (exit 0) and on a
 *     copy with one cell changed (exit 1, naming the file), so the check is shown able to fail.
 *   - **The shape** (counts only, near the shape of the owner's example workbook, plan section 11):
 *     the produced numbers are pinned here and in the README. Every value in every file is invented;
 *     nothing was taken from the owner's workbooks, which this repository has never held.
 *   - **Placeholders only**: every cell has the shape of an invented name; no `@` anywhere.
 *     (`tests/realNameDenylist.test.js` scans `fixtures/` as well.)
 *   - **The plants are counted from the CSV, not from the generator.** A small sweep written in this
 *     file (all pairs, no sorting tricks) finds the clashes in `schedule.csv`; `evaluateGameSchedule`,
 *     the Games page's own report, is asked the same question; the generator's bookkeeping is the
 *     third count. All three must agree, and the set of games each plant touched must be the set the
 *     sweep flags. The pre-plant copy (`plants: false`) is the control: the same sweep and the same
 *     report find nothing there, so the check was able to fail (lesson: a check that examined
 *     nothing is a failure, not a pass).
 *
 * Statically out of reach, and so not claimed: that the shape is the same shape as the owner's
 * workbook beyond the counts the plan lists (the workbook is not in this repository), and that
 * `schedule-invalid.csv` is judged as the importer will judge it. That second half is
 * `tests/scheduleImportParse.test.js`, which reads the expectation each row carries in `Notes`.
 */

import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import Papa from 'papaparse';
import { afterAll, describe, expect, it } from 'vitest';
import { evaluateGameSchedule } from '../packages/core/src/gameMetrics.js';
import { resolveZonedInstant } from '../packages/core/src/timing/seasonClock.js';
import {
  FIXTURE_SEASON,
  PLANT_COUNTS,
  SCHEDULE_FIXTURE_DIR,
  buildScheduleFixture,
  fixtureDifferences,
} from '../scripts/build-schedule-fixture.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SCRIPT = path.join(HERE, '..', 'scripts', 'build-schedule-fixture.mjs');
const FILES = ['schedule.csv', 'teams.csv', 'venues.csv', 'schedule-invalid.csv'];

const scratch = mkdtempSync(path.join(tmpdir(), 'schedule-fixture-'));
afterAll(() => rmSync(scratch, { recursive: true, force: true }));

/** @param {string} text */
function parseCsv(text) {
  const { data, meta, errors } = Papa.parse(text, { header: true, skipEmptyLines: true });
  expect(errors).toEqual([]);
  return { rows: /** @type {Record<string, string>[]} */ (data), fields: meta.fields ?? [] };
}
/** @param {string} file */
const onDisk = (file) => parseCsv(readFileSync(path.join(SCHEDULE_FIXTURE_DIR, file), 'utf8'));

const SCHEDULE = onDisk('schedule.csv');
const TEAMS = onDisk('teams.csv');
const VENUES = onDisk('venues.csv');
const INVALID = onDisk('schedule-invalid.csv');

const FORMAT_HEADERS = [
  'Game ID',
  'Date',
  'Start Time',
  'End Time',
  'Venue',
  'Field',
  'Division',
  'Home Team',
  'Away Team',
  'Week',
  'Format',
];

/* -------------------------------------------------------------------------- */
/* An independent reading of a schedule: all pairs, from the CSV text alone     */
/* -------------------------------------------------------------------------- */

/** @param {string} hhmm */
const minutes = (hhmm) => Number(hhmm.slice(0, 2)) * 60 + Number(hhmm.slice(3, 5));
/** @param {{ start: string, end: string }} a @param {{ start: string, end: string }} b */
const overlaps = (a, b) => minutes(a.start) < minutes(b.end) && minutes(b.start) < minutes(a.end);

/**
 * @param {Record<string, string>[]} rows schedule rows
 * @param {Map<string, string[]>} coachesOf own team label -> coach names
 */
function sweep(rows, coachesOf) {
  const timed = rows.filter((r) => r['Start Time'] !== '' && r['End Time'] !== '');
  const item = (r) => ({
    id: r['Game ID'],
    start: r['Start Time'],
    end: r['End Time'],
  });

  /** same field, same day */
  const byField = new Map();
  for (const r of timed) {
    const key = `${r.Date}|${r.Venue}|${r.Field}`;
    byField.set(key, [...(byField.get(key) ?? []), item(r)]);
  }
  const fieldClashes = [];
  for (const [key, items] of byField) {
    const pairs = [];
    for (let i = 0; i < items.length; i += 1)
      for (let j = i + 1; j < items.length; j += 1)
        if (overlaps(items[i], items[j])) pairs.push([items[i].id, items[j].id]);
    if (pairs.length > 0) fieldClashes.push({ key, pairs });
  }

  /** one own team in two games at once, one coach in two games at once */
  const sides = (r) => [
    { team: r['Home Team'], role: 'home' },
    { team: r['Away Team'], role: 'away' },
  ];
  const byTeam = new Map();
  const byCoach = new Map();
  for (const r of timed) {
    for (const { team, role } of sides(r)) {
      if (!coachesOf.has(team)) continue; // an outside club: not an own team
      const key = `${r.Date}|${team}`;
      byTeam.set(key, [...(byTeam.get(key) ?? []), { ...item(r), role }]);
      for (const coach of coachesOf.get(team)) {
        const ckey = `${r.Date}|${coach}`;
        byCoach.set(ckey, [...(byCoach.get(ckey) ?? []), { ...item(r), role, team }]);
      }
    }
  }
  const clashesIn = (groups) => {
    const found = [];
    for (const [key, items] of groups) {
      const hits = [];
      for (let i = 0; i < items.length; i += 1)
        for (let j = i + 1; j < items.length; j += 1)
          if (items[i].id !== items[j].id && overlaps(items[i], items[j]))
            hits.push([items[i], items[j]]);
      if (hits.length > 0) found.push({ key, hits });
    }
    return found;
  };
  const teamClashes = clashesIn(byTeam);
  const coachClashes = clashesIn(byCoach);

  /** hosting: an own team's home minus away games over the games with a time */
  const load = new Map();
  for (const r of timed)
    for (const { team, role } of sides(r)) {
      if (!coachesOf.has(team)) continue;
      const tally = load.get(team) ?? { home: 0, away: 0 };
      tally[role] += 1;
      load.set(team, tally);
    }
  const imbalanced = [...load].filter(([, t]) => Math.abs(t.home - t.away) > 1).map(([n]) => n);

  return {
    examined: {
      games: timed.length,
      fieldDays: byField.size,
      teamDays: byTeam.size,
      coachDays: byCoach.size,
      teamsWithGames: load.size,
    },
    fieldClashes,
    teamClashes,
    coachClashes,
    imbalanced,
  };
}

/** @param {Record<string, string>[]} teamRows */
function coachMap(teamRows) {
  return new Map(
    teamRows.map((t) => [
      t.Team,
      [t['Coach 1'], t['Coach 2'], t['Coach 3']].filter((c) => c !== ''),
    ])
  );
}

/**
 * What the Games page's own report says about a schedule: the CSV becomes assignments on the
 * season clock, own teams carry their coaches, and each outside (division, label) is a team with
 * none, as the importer will store it.
 */
function reportOf(scheduleRows, teamRows) {
  const coachIdOf = (name) => `coach|${name}`;
  const teams = teamRows.map((t) => ({
    id: t.Team,
    division: t.Division,
    coachId: coachIdOf(t['Coach 1']),
    assistantCoachIds: [t['Coach 2'], t['Coach 3']].filter((c) => c !== '').map(coachIdOf),
  }));
  const own = new Set(teams.map((t) => t.id));
  const idOf = (r, label) => (own.has(label) ? label : `outside|${r.Division}|${label}`);
  const assignments = [];
  for (const r of scheduleRows) {
    if (r['Start Time'] === '' || r['End Time'] === '') continue;
    for (const label of [r['Home Team'], r['Away Team']]) {
      const id = idOf(r, label);
      if (!own.has(label) && !teams.some((t) => t.id === id))
        teams.push({ id, division: r.Division });
    }
    assignments.push({
      weekIndex: Number(r.Week),
      division: r.Division,
      slotId: r['Game ID'],
      id: r['Game ID'],
      start: resolveZonedInstant({
        date: r.Date,
        time: r['Start Time'],
        timeZone: FIXTURE_SEASON.timeZone,
      }).iso,
      end: resolveZonedInstant({
        date: r.Date,
        time: r['End Time'],
        timeZone: FIXTURE_SEASON.timeZone,
      }).iso,
      homeTeamId: idOf(r, r['Home Team']),
      awayTeamId: idOf(r, r['Away Team']),
      fieldId: `${r.Venue}|${r.Field}`,
    });
  }
  const { warnings } = evaluateGameSchedule({ assignments, teams });
  /** @type {Record<string, number>} */
  const byType = {};
  for (const w of warnings) byType[w.type] = (byType[w.type] ?? 0) + 1;
  return { byType, warnings, gameCount: assignments.length };
}

const TEAM_COACHES = coachMap(TEAMS.rows);

/* -------------------------------------------------------------------------- */

describe('schedule fixture: the files are the generator output', () => {
  const built = buildScheduleFixture();

  it('holds exactly the four generated files, byte for byte', () => {
    expect(Object.keys(built.files).sort()).toEqual([...FILES].sort());
    for (const file of FILES) {
      expect(readFileSync(path.join(SCHEDULE_FIXTURE_DIR, file), 'utf8')).toBe(built.files[file]);
    }
    expect(fixtureDifferences()).toEqual([]);
  });

  it('keeps a README beside them', () => {
    const names = readdirSync(SCHEDULE_FIXTURE_DIR);
    expect(names).toContain('README.md');
    expect(names.filter((n) => n !== 'README.md').sort()).toEqual([...FILES].sort());
  });

  it('is deterministic, and does not read the host time zone', () => {
    const original = process.env.TZ;
    try {
      process.env.TZ = 'Pacific/Auckland';
      const auckland = buildScheduleFixture();
      process.env.TZ = 'America/New_York';
      const newYork = buildScheduleFixture();
      expect(auckland.files).toEqual(built.files);
      expect(newYork.files).toEqual(built.files);
    } finally {
      if (original === undefined) delete process.env.TZ;
      else process.env.TZ = original;
    }
  });

  it('--check exits 0 on the real directory', () => {
    const run = spawnSync(process.execPath, [SCRIPT, '--check'], { encoding: 'utf8' });
    expect(run.status).toBe(0);
  });

  it('--check exits 1 on a copy with one cell changed, and names the file', () => {
    const copy = path.join(scratch, 'one-cell');
    cpSync(SCHEDULE_FIXTURE_DIR, copy, { recursive: true });
    const control = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(control.status).toBe(0); // the copy is clean first, so the failure below is the edit's
    const text = readFileSync(path.join(copy, 'schedule.csv'), 'utf8');
    writeFileSync(path.join(copy, 'schedule.csv'), text.replace('Venue A', 'Venue Z'));
    const run = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(run.status).toBe(1);
    expect(run.stderr).toContain('schedule.csv');
  });

  it('--check exits 1 on a copy missing a file', () => {
    const copy = path.join(scratch, 'missing');
    cpSync(SCHEDULE_FIXTURE_DIR, copy, { recursive: true });
    rmSync(path.join(copy, 'teams.csv'));
    const run = spawnSync(process.execPath, [SCRIPT, '--check', '--dir', copy], {
      encoding: 'utf8',
    });
    expect(run.status).toBe(1);
    expect(run.stderr).toContain('teams.csv');
  });
});

describe('schedule fixture: shape (counts only; every value is invented)', () => {
  const rows = SCHEDULE.rows;
  const ownLabels = new Set(TEAMS.rows.map((t) => t.Team));
  const outsideRows = rows.filter(
    (r) => !ownLabels.has(r['Home Team']) || !ownLabels.has(r['Away Team'])
  );
  const distinct = (values) => new Set(values).size;

  it('has the documented columns (the import format of plan 4.3, plus the dropped Format)', () => {
    expect(SCHEDULE.fields).toEqual(FORMAT_HEADERS);
    expect(TEAMS.fields).toEqual(['Team', 'Division', 'Coach 1', 'Coach 2', 'Coach 3']);
    expect(VENUES.fields).toEqual(['Venue', 'Field']);
    expect(INVALID.fields).toEqual([...FORMAT_HEADERS.filter((h) => h !== 'Format'), 'Notes']);
  });

  it('is 574 games on 9 Saturdays at 7 venues and 26 fields across 20 divisions', () => {
    expect(rows).toHaveLength(574);
    const dates = [...new Set(rows.map((r) => r.Date))].sort();
    expect(dates).toHaveLength(9);
    for (const d of dates) expect(new Date(`${d}T00:00:00Z`).getUTCDay()).toBe(6); // Saturday
    expect(distinct(rows.map((r) => r.Venue))).toBe(7);
    expect(distinct(rows.map((r) => `${r.Venue}|${r.Field}`))).toBe(26);
    expect(distinct(rows.map((r) => r.Division))).toBe(20);
    // games on a date: close to the example's 59 to 67
    for (const d of dates) {
      const n = rows.filter((r) => r.Date === d).length;
      expect(n).toBeGreaterThanOrEqual(59);
      expect(n).toBeLessThanOrEqual(70);
    }
  });

  it('lists the 26 fields and 7 venues the schedule uses, and nothing else', () => {
    expect(VENUES.rows).toHaveLength(26);
    expect(distinct(VENUES.rows.map((v) => v.Venue))).toBe(7);
    expect(new Set(VENUES.rows.map((v) => `${v.Venue}|${v.Field}`))).toEqual(
      new Set(rows.map((r) => `${r.Venue}|${r.Field}`))
    );
  });

  it('has 132 own teams in 20 divisions, 215 coach seats held by 196 people', () => {
    expect(TEAMS.rows).toHaveLength(132);
    expect(distinct(TEAMS.rows.map((t) => t.Team))).toBe(132);
    expect(distinct(TEAMS.rows.map((t) => t.Division))).toBe(20);
    expect(TEAMS.rows.every((t) => t['Coach 1'] !== '')).toBe(true);
    expect(TEAMS.rows.filter((t) => t['Coach 2'] !== '')).toHaveLength(82);
    expect(TEAMS.rows.filter((t) => t['Coach 3'] !== '')).toHaveLength(1);
    // a third coach implies a second
    for (const t of TEAMS.rows) if (t['Coach 3'] !== '') expect(t['Coach 2']).not.toBe('');
    const seats = TEAMS.rows
      .flatMap((t) => [t['Coach 1'], t['Coach 2'], t['Coach 3']])
      .filter(Boolean);
    expect(seats).toHaveLength(215);
    expect(distinct(seats)).toBe(196);
    // no coach is named twice on one team, and none coaches in a team's own division twice
    for (const t of TEAMS.rows) {
      const names = [t['Coach 1'], t['Coach 2'], t['Coach 3']].filter(Boolean);
      expect(distinct(names)).toBe(names.length);
    }
  });

  it('has 43 games against outside clubs: 31 labels, one venue, six divisions', () => {
    expect(outsideRows).toHaveLength(43);
    // exactly one side of each is an own team
    for (const r of outsideRows) {
      const ownSides = [r['Home Team'], r['Away Team']].filter((l) => ownLabels.has(l));
      expect(ownSides).toHaveLength(1);
    }
    const labels = outsideRows.map((r) =>
      ownLabels.has(r['Home Team']) ? r['Away Team'] : r['Home Team']
    );
    expect(distinct(labels)).toBe(31);
    expect(distinct(outsideRows.map((r) => r.Venue))).toBe(1);
    expect(distinct(outsideRows.map((r) => r.Division))).toBe(6);
    // one (division, label) pair is one outside team row at import: none is used twice
    expect(distinct(outsideRows.map((r, i) => `${r.Division}|${labels[i]}`))).toBe(43);
    // an outside label is never an own team's name
    for (const l of labels) expect(ownLabels.has(l)).toBe(false);
  });

  it('puts every own team in its own division, and every game within one division', () => {
    const divisionOf = new Map(TEAMS.rows.map((t) => [t.Team, t.Division]));
    for (const r of rows) {
      for (const label of [r['Home Team'], r['Away Team']]) {
        if (divisionOf.has(label)) expect(divisionOf.get(label)).toBe(r.Division);
      }
    }
  });

  it('gives every game a unique Game ID, a Week that follows the date, and a Format', () => {
    expect(distinct(rows.map((r) => r['Game ID']))).toBe(574);
    // The week rule of plan 4.8, written out here: one plus the whole weeks since the Monday of the
    // week the season starts.
    const mondayOf = (iso) => {
      const d = new Date(`${iso}T00:00:00Z`);
      d.setUTCDate(d.getUTCDate() - ((d.getUTCDay() + 6) % 7));
      return d.getTime();
    };
    const first = mondayOf(FIXTURE_SEASON.startDate);
    for (const r of rows) {
      expect(Number(r.Week)).toBe(1 + Math.floor((mondayOf(r.Date) - first) / (7 * 86400000)));
      expect(r.Format).toMatch(/^(4v4|5v5|7v7|9v9|11v11)$/);
    }
    expect(Math.max(...rows.map((r) => Number(r.Week)))).toBe(9);
  });

  it('plays each own team at most once a week, and at most nine games', () => {
    const perTeamWeek = new Map();
    for (const r of rows)
      for (const label of [r['Home Team'], r['Away Team']]) {
        if (!ownLabels.has(label)) continue;
        const key = `${label}|${r.Week}`;
        perTeamWeek.set(key, (perTeamWeek.get(key) ?? 0) + 1);
      }
    expect(Math.max(...perTeamWeek.values())).toBe(1);
    const perTeam = new Map();
    for (const key of perTeamWeek.keys()) {
      const team = key.split('|')[0];
      perTeam.set(team, (perTeam.get(team) ?? 0) + 1);
    }
    expect(Math.max(...perTeam.values())).toBeLessThanOrEqual(9);
    expect(perTeam.size).toBe(132); // every own team plays
  });

  it('uses the season the README states', () => {
    expect(FIXTURE_SEASON).toEqual({
      timeZone: 'America/Los_Angeles',
      startDate: '2026-09-07',
      endDate: '2027-03-31',
    });
  });
});

describe('schedule fixture: placeholders only', () => {
  const COACH = /^CoachFirst(\d+) CoachLast\1$/;

  it('shapes every cell of schedule.csv', () => {
    for (const r of SCHEDULE.rows) {
      expect(r['Game ID']).toMatch(/^G-\d{4}$/);
      expect(r.Date).toMatch(/^2026-\d\d-\d\d$/);
      expect(r.Venue).toMatch(/^Venue [A-G]$/);
      expect(r.Field).toMatch(/^Field \d$/);
      expect(r.Division).toMatch(/^U\d\d (Boys|Girls)$/);
      expect(r.Week).toMatch(/^[1-9]$/);
      for (const label of [r['Home Team'], r['Away Team']])
        expect(label).toMatch(/^U\d\d[BG] Team \d\d$|^Visiting Club [A-Z]{1,2}$/);
      const timed = r['Start Time'] !== '' || r['End Time'] !== '';
      if (timed) {
        expect(r['Start Time']).toMatch(/^\d\d:\d\d$/);
        expect(r['End Time']).toMatch(/^\d\d:\d\d$/);
        expect(minutes(r['End Time'])).toBeGreaterThan(minutes(r['Start Time']));
      }
    }
  });

  it('shapes teams.csv and venues.csv', () => {
    for (const t of TEAMS.rows) {
      expect(t.Team).toMatch(/^U\d\d[BG] Team \d\d$/);
      expect(t.Division).toMatch(/^U\d\d (Boys|Girls)$/);
      for (const c of [t['Coach 1'], t['Coach 2'], t['Coach 3']])
        if (c !== '') expect(c).toMatch(COACH);
    }
    for (const v of VENUES.rows) {
      expect(v.Venue).toMatch(/^Venue [A-G]$/);
      expect(v.Field).toMatch(/^Field \d$/);
    }
  });

  it('numbers coaches by first appearance in teams.csv, as the demo fixture does', () => {
    const seen = [];
    for (const t of TEAMS.rows)
      for (const c of [t['Coach 1'], t['Coach 2'], t['Coach 3']])
        if (c !== '' && !seen.includes(c)) seen.push(c);
    seen.forEach((name, i) => expect(name).toBe(`CoachFirst${i + 1} CoachLast${i + 1}`));
  });

  it('has no email address, phone number or `@` in any file', () => {
    for (const file of FILES) {
      const text = readFileSync(path.join(SCHEDULE_FIXTURE_DIR, file), 'utf8');
      expect(text).not.toContain('@');
      expect(text).not.toMatch(/\d{3}-\d{3,4}/);
    }
  });

  it('shapes every cell of schedule-invalid.csv, whose Notes say what each row is for', () => {
    for (const r of INVALID.rows) {
      expect(r['Game ID']).toMatch(/^X-\d{3}$/);
      expect(r.Notes).toMatch(/^expect: [a-z-]+( [a-z-]+)?$/);
      for (const label of [r['Home Team'], r['Away Team']])
        // case and spacing may differ on purpose (the same-team row), the words may not
        expect(label).toMatch(
          /^U\d\d[BG]\s+Team\s+\d\d$|^Visiting Club [A-Z]{1,2}$|^Unlisted Team \d\d$/i
        );
    }
  });
});

describe('schedule fixture: the plants, counted from the CSV', () => {
  const planted = buildScheduleFixture();
  const control = buildScheduleFixture({ plants: false });
  const controlSchedule = parseCsv(control.files['schedule.csv']);
  const controlTeams = parseCsv(control.files['teams.csv']);

  it('states its plant counts', () => {
    expect(PLANT_COUNTS).toEqual({
      sameFieldOverlaps: 3,
      coachClashes: 3,
      hostingImbalances: 3,
      blankTimes: 1,
    });
    for (const [name, count] of Object.entries(PLANT_COUNTS)) {
      expect(planted.plants[name].count).toBe(count);
    }
    // the games each plant touched: both games of a clash, the one flipped game, the one blanked
    expect(planted.plants.sameFieldOverlaps.gameIds).toHaveLength(6);
    expect(planted.plants.coachClashes.gameIds).toHaveLength(6);
    expect(planted.plants.hostingImbalances.gameIds).toHaveLength(3);
    expect(planted.plants.blankTimes.gameIds).toHaveLength(1);
  });

  it('the sweep finds the planted clashes in the CSV, and the Games page report agrees', () => {
    const found = sweep(SCHEDULE.rows, TEAM_COACHES);
    // The sweep looked at something (a meta-assertion: a sweep over nothing finds nothing).
    expect(found.examined.games).toBe(573);
    expect(found.examined.fieldDays).toBeGreaterThan(100);
    expect(found.examined.coachDays).toBeGreaterThan(500);
    expect(found.examined.teamsWithGames).toBe(132);

    expect(found.fieldClashes).toHaveLength(PLANT_COUNTS.sameFieldOverlaps);
    expect(found.coachClashes).toHaveLength(PLANT_COUNTS.coachClashes);
    expect(found.imbalanced).toHaveLength(PLANT_COUNTS.hostingImbalances);
    expect(found.teamClashes).toHaveLength(0);
    // each clashing field and coach is in exactly one overlapping pair, so a count of subjects
    // and a count of pairs are the same number
    for (const c of found.fieldClashes) expect(c.pairs).toHaveLength(1);
    for (const c of found.coachClashes) expect(c.hits).toHaveLength(1);

    const report = reportOf(SCHEDULE.rows, TEAMS.rows);
    expect(report.gameCount).toBe(573);
    expect(report.byType).toEqual({
      'field-overlap': PLANT_COUNTS.sameFieldOverlaps,
      'coach-conflict': PLANT_COUNTS.coachClashes,
      'home-away-imbalance': PLANT_COUNTS.hostingImbalances,
    });
  });

  it('the generator\u2019s own record names exactly the games the sweep flags', () => {
    const found = sweep(SCHEDULE.rows, TEAM_COACHES);
    const fieldGames = new Set(found.fieldClashes.flatMap((c) => c.pairs.flat()));
    expect(new Set(planted.plants.sameFieldOverlaps.gameIds)).toEqual(fieldGames);
    const coachGames = new Set(found.coachClashes.flatMap((c) => c.hits.flat().map((h) => h.id)));
    expect(new Set(planted.plants.coachClashes.gameIds)).toEqual(coachGames);
    // hostingImbalances records the flipped games; the sweep names teams, so check the teams
    const flipped = SCHEDULE.rows.filter((r) =>
      planted.plants.hostingImbalances.gameIds.includes(r['Game ID'])
    );
    expect(flipped).toHaveLength(PLANT_COUNTS.hostingImbalances);
    const sides = new Set(flipped.flatMap((r) => [r['Home Team'], r['Away Team']]));
    for (const team of found.imbalanced) expect(sides.has(team)).toBe(true);
    const blank = SCHEDULE.rows.filter((r) => r['Start Time'] === '' && r['End Time'] === '');
    expect(blank.map((r) => r['Game ID'])).toEqual(planted.plants.blankTimes.gameIds);
  });

  it('puts the coach clash on an away side (so a check of the home side alone misses it)', () => {
    const found = sweep(SCHEDULE.rows, TEAM_COACHES);
    const onAway = found.coachClashes.filter((c) => c.hits[0].some((h) => h.role === 'away'));
    expect(onAway.length).toBeGreaterThanOrEqual(1);
    // and at least one clash sits on an away side in BOTH of its games' reading of the other
    const homeOnly = found.coachClashes.filter((c) => c.hits[0].every((h) => h.role === 'home'));
    expect(homeOnly.length).toBeLessThan(found.coachClashes.length);
  });

  it('the pre-plant copy reports none: the same sweep, the same report, nothing found', () => {
    const found = sweep(controlSchedule.rows, coachMap(controlTeams.rows));
    expect(found.examined.games).toBe(574); // every game has a time before the plants
    expect(found.examined.coachDays).toBeGreaterThan(500);
    expect(found.fieldClashes).toEqual([]);
    expect(found.coachClashes).toEqual([]);
    expect(found.teamClashes).toEqual([]);
    expect(found.imbalanced).toEqual([]);
    const report = reportOf(controlSchedule.rows, controlTeams.rows);
    expect(report.gameCount).toBe(574);
    expect(report.byType).toEqual({});
  });

  it('the plants changed only the games they name, and added or removed no game', () => {
    expect(controlSchedule.rows).toHaveLength(574);
    expect(controlTeams.rows).toEqual(TEAMS.rows); // the plants move games, never coaches
    expect(controlSchedule.rows.map((r) => r['Game ID'])).toEqual(
      SCHEDULE.rows.map((r) => r['Game ID'])
    );
    const touched = new Set(Object.values(planted.plants).flatMap((p) => p.gameIds));
    const changed = SCHEDULE.rows
      .filter((r, i) => JSON.stringify(r) !== JSON.stringify(controlSchedule.rows[i]))
      .map((r) => r['Game ID']);
    // A clash names both its games; only the moved one differs from the control. So every changed
    // game is one a plant names, and there is one changed game per plant count.
    for (const id of changed) expect(touched.has(id)).toBe(true);
    expect(changed).toHaveLength(Object.values(PLANT_COUNTS).reduce((a, b) => a + b, 0));
    // the control carries no row without a time
    expect(controlSchedule.rows.filter((r) => r['Start Time'] === '')).toHaveLength(0);
    expect(SCHEDULE.rows.filter((r) => r['Start Time'] === '')).toHaveLength(1);
  });

  it('the sweep can fail: planting a clash into a copy of the control is found', () => {
    const rows = controlSchedule.rows.map((r) => ({ ...r }));
    const [a, b] = rows.filter((r) => r.Date === rows[0].Date && r.Field !== rows[0].Field);
    // put game b on game a's field at game a's time
    b.Venue = a.Venue;
    b.Field = a.Field;
    b['Start Time'] = a['Start Time'];
    b['End Time'] = a['End Time'];
    const found = sweep(rows, coachMap(controlTeams.rows));
    expect(found.fieldClashes).toHaveLength(1);
    expect(found.fieldClashes[0].pairs[0].sort()).toEqual([a['Game ID'], b['Game ID']].sort());
  });
});

describe('schedule fixture: schedule-invalid.csv', () => {
  /** The closed lists of plan 4.4 (and 4.8), written out here rather than imported. */
  const ROW_REASONS = [
    'bad-date',
    'bad-time',
    'end-not-after-start',
    'same-team',
    'time-in-dst-gap',
    'outside-season-window',
    'unknown-division',
    'unknown-team',
    'unknown-venue',
    'unknown-field',
    'label-is-own-team',
    'duplicate-row',
    'game-id-reused',
    'bad-week',
  ];
  const ACCEPTED = ['ok', 'tbd', 'time-ambiguous', 'week-differs'];
  const expectations = INVALID.rows.map((r) => r.Notes.replace(/^expect: /, ''));

  it('has about twenty rows and one for every refusal reason', () => {
    expect(INVALID.rows.length).toBeGreaterThanOrEqual(20);
    expect(INVALID.rows.length).toBeLessThanOrEqual(32);
    for (const reason of ROW_REASONS) expect(expectations).toContain(reason);
  });

  it('also carries the accepted rows: a plain control, a TIME TBD row, the two flags', () => {
    for (const kind of ACCEPTED) expect(expectations).toContain(kind);
    for (const e of expectations) expect([...ROW_REASONS, ...ACCEPTED]).toContain(e.split(' ')[0]);
  });

  it('uses the US date form and the 12-hour time form in rows that are valid', () => {
    const valid = INVALID.rows.filter((r) => r.Notes === 'expect: ok');
    expect(valid.some((r) => /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(r.Date))).toBe(true);
    expect(valid.some((r) => /^\d{1,2}:\d{2} [AP]M$/i.test(r['Start Time']))).toBe(true);
    expect(valid.some((r) => /^12:\d\d [AP]M$/i.test(r['Start Time']))).toBe(true);
    // and the swapped-day-and-month case the parser must not "repair"
    expect(
      INVALID.rows.some((r) => r.Date === '13/04/2026' && r.Notes === 'expect: bad-date')
    ).toBe(true);
  });

  it('repeats a Game ID only where a reason says so', () => {
    const byId = new Map();
    for (const r of INVALID.rows) byId.set(r['Game ID'], [...(byId.get(r['Game ID']) ?? []), r]);
    const repeated = [...byId.values()].filter((g) => g.length > 1);
    expect(repeated).toHaveLength(2);
    for (const group of repeated) {
      expect(group[0].Notes).toBe('expect: ok');
      expect(['expect: duplicate-row', 'expect: game-id-reused']).toContain(group[1].Notes);
    }
    expect(repeated.map((g) => g[1].Notes).sort()).toEqual([
      'expect: duplicate-row',
      'expect: game-id-reused',
    ]);
  });
});
